function resetMotion(){started=performance.now();orbitTheta=orbitPhi=0;zoom=1;motion=0;}
function changeStep(n){if(n<0||n>10)return;step=n;renderBook();resetMotion();$('#page-turn').classList.remove('flip');void $('#page-turn').offsetWidth;$('#page-turn').classList.add('flip');}
$('#next').onclick=()=>changeStep(step===10?0:step+1);$('#prev').onclick=()=>changeStep(step-1);$('#replay').onclick=resetMotion;$('#reset-view').onclick=()=>{orbitTheta=orbitPhi=0;zoom=1;};$('#zoom-in').onclick=()=>zoom=Math.max(.55,zoom-.12);$('#zoom-out').onclick=()=>zoom=Math.min(2.8,zoom+.12);
