$('#collapse-book').onclick=toggleBook;$('#open-book').onclick=toggleBook;$('#info').onclick=()=>$('#about').showModal();$('#close-info').onclick=()=>$('#about').close();$('#about').onclick=e=>{if(e.target===$('#about'))$('#about').close();};
