 if(step>=6){for(const b of allLowerBolts)showBolt(b,true);for(const b of allPairs)showBolt(b,true);for(const p of model.lower)put(p,true);for(const b of model.woodScrews)showBolt(b,true);}
 if(step>=6&&step<=8){rootQ=qx(Math.PI);rootY=.476;chassisY=step===6?-.32*(1-enter):0;desiredAt.set(0,.235,0);desiredCamera.set(1.13,1.12,1.45);if(step>=7){model.mount.forEach(b=>showBolt(b,true,step===7?screwP:1,.10));}if(step===7)active=model.mount[0];if(step===8){model.feet.forEach(f=>showBolt(f,true,screwP,.085));active=model.feet[0];}}
 if(step>=9){model.mount.forEach(b=>showBolt(b,true));model.feet.forEach(f=>showBolt(f,true));model.upper.forEach(b=>put(b,true,[0,0,step===9?Math.sign(b.userData.base.z)*.13*(1-enter):0]));allUpperBolts.forEach(b=>showBolt(b,true,step===9?screwP:1,.10));if(step===9)active=allUpperBolts[0];}
 if(step===10){desiredAt.set(0,.23,0);desiredCamera.set(1.02,.86,1.30);cloth.visible=false;}
 model.root.quaternion.slerp(rootQ,ease);model.root.position.y=lerp(model.root.position.y,rootY,ease);model.chassis.position.y=lerp(model.chassis.position.y,chassisY,ease);model.crown.position.y=lerp(model.crown.position.y,crownY,ease);model.chassis.visible=chassisVisible;model.crown.visible=crownVisible;
